// Export the generated Authfly widgets of the eight runtimes from the codegen build (.cache/codegen/packages/<rt>/ui) into
// packages/ui/<rt>: the primitives, helpers and styles as generated, plus the Authfly blocks and the files they reference
// (dependency closure). Plain local sets: copy a folder into an app, or import it by path. Generated files keep their
// "Code generated by xgen. DO NOT EDIT." header; regenerate with tools/gen-ui.sh.
import { cpSync, existsSync, mkdirSync, readdirSync, readFileSync, rmSync, statSync, writeFileSync } from "node:fs";
import { basename, dirname, join, relative, resolve } from "node:path";

const [cg, out] = [resolve(process.argv[2]!), resolve(process.argv[3]!)];
const RT = ["react", "svelte", "vue", "solid", "templ", "twig", "latte", "jinja2"] as const;
const skipTop = new Set([".venv", ".xgen-manifest.json", "__pycache__", "node_modules", "vendor", "blocks", "components", "presets", "bin", "README.md", "index.ts", "composer.lock", "package.json"]);

function copyTree(from: string, to: string) {
  for (const e of readdirSync(from)) {
    if (skipTop.has(e)) continue;
    cpSync(join(from, e), join(to, e), { recursive: true });
  }
}
/** relative references of a file to other files of the package */
function refs(file: string, text: string, pkg: string): string[] {
  const found: string[] = [];
  const dir = dirname(file);
  for (const m of text.matchAll(/from\s+["'](\.{1,2}\/[^"']+)["']/g)) {
    const base = resolve(dir, m[1]!);
    for (const ext of ["", ".ts", ".tsx", ".svelte", ".vue", ".types.ts"]) if (existsSync(base + ext) && statSync(base + ext).isFile()) { found.push(base + ext); break; }
  }
  for (const m of text.matchAll(/["']((?:blocks|components)\/[a-z0-9-]+\.(?:html\.twig|latte|html\.j2))["']/g)) found.push(join(pkg, m[1]!));
  return found.filter((f) => !f.includes("/primitives/") && !f.includes("/utils/") && !f.includes("/styles/"));
}

for (const rt of RT) {
  const pkg = join(cg, "packages", rt, "ui");
  const dst = join(out, rt);
  rmSync(dst, { recursive: true, force: true });
  mkdirSync(dst, { recursive: true });
  const ts = ["react", "svelte", "vue", "solid"].includes(rt);
  const src = ts ? join(pkg, "src") : pkg;
  const dsrc = ts ? join(dst, "src") : dst;
  mkdirSync(dsrc, { recursive: true });
  copyTree(src, dsrc);
  for (const f of ["package.json", "tsconfig.json", "composer.json", "requirements.txt", "pyproject.toml", "go.mod", "go.sum"]) if (existsSync(join(pkg, f)) && !ts || (ts && f === "tsconfig.json" && existsSync(join(pkg, f)))) cpSync(join(pkg, f), join(dst, f));
  // the closure of the Authfly blocks
  const blocksDir = join(src, "blocks");
  const queue = readdirSync(blocksDir).filter((f) => f.startsWith("authfly-")).map((f) => join(blocksDir, f));
  if (rt === "templ") queue.push(...readdirSync(blocksDir).filter((f) => /^field(\.templ|_templ\.go)$/.test(f)).map((f) => join(blocksDir, f)));
  const seen = new Set<string>();
  while (queue.length) {
    const f = queue.pop()!;
    if (seen.has(f) || !existsSync(f)) continue;
    seen.add(f);
    if (rt !== "templ") queue.push(...refs(f, readFileSync(f, "utf8"), src));
  }
  for (const f of seen) {
    const to = join(dsrc, relative(src, f));
    mkdirSync(dirname(to), { recursive: true });
    cpSync(f, to);
  }
  if (ts) {
    const ext = rt === "svelte" ? ".svelte" : rt === "vue" ? ".vue" : "";
    const names = [...seen].filter((f) => basename(f).startsWith("authfly-") && !f.endsWith(".types.ts")).map((f) => basename(f).replace(/\.(tsx|svelte|vue)$/, ""));
    const pascal = (n: string) => n.split("-").map((s) => s[0]!.toUpperCase() + s.slice(1)).join("");
    const lines = names.sort().map((n) => (ext ? `export { default as ${pascal(n)} } from "./blocks/${n}${ext}";` : `export { ${pascal(n)} } from "./blocks/${n}";`));
    writeFileSync(join(dsrc, "authfly.ts"), `// Authfly widgets (generated by tools/export-ui.ts). DO NOT EDIT.\n${lines.join("\n")}\n`);
  }
  console.log(`${rt.padEnd(7)} ${[...seen].length} block files -> ${relative(process.cwd(), dst)}`);
}

// ui8px policy fixes on the exported copies (the upstream build is untouched):
// - Go unit tests of the cn helper hold deliberately conflicting class lists; they are not part of the widget set.
// - shadcn's base layer applies `outline-ring/50`, which ui8px does not know; the same rule as plain CSS.
function walk(dir: string, fn: (f: string) => void) {
  for (const e of readdirSync(dir)) { const p = join(dir, e); statSync(p).isDirectory() ? walk(p, fn) : fn(p); }
}
// - templ only: the parity harness (cmd/) and the two primitives the Authfly set never renders (sheet, disclosure) use
//   variant modifiers ui8px has no grammar for (group-open, in-aria-expanded); they stay in codegen, not in the export.
for (const d of ["cmd", "ui/sheet", "ui/disclosure"]) rmSync(join(out, "templ", d), { recursive: true, force: true });
walk(out, (f) => {
  if (f.endsWith("_test.go")) rmSync(f);
  else if (f.endsWith("/styles/theme.css")) {
    const t = readFileSync(f, "utf8");
    writeFileSync(f, t.replace("@apply border-border outline-ring/50;", "@apply border-border;\n    outline-color: color-mix(in oklab, var(--ring) 50%, transparent);"));
  }
});
